178	    /**
179	     * The known E.164 country calling codes used to split the stored telephone into its country
180	     * code and national digits when formatting {@link #getTelephoneDisplay()}. Ordered
181	     * longest-first so the most specific code wins; this mirrors the codes the application
182	     * recognises elsewhere (Australia {@code '+61'} and the NANP {@code '+1'}).
183	     */
184	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
