186	    /**
187	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
188	     * national digits grouped in threes from the left and separated by spaces. So the stored
189	     * {@code '+61412345678'} is displayed as {@code '+61 412 345 678'}. The raw {@link #telephone}
190	     * itself is left in E.164 form. A {@code null} telephone yields {@code null}, and a value not in
191	     * E.164 form (no leading {@code '+'}) is returned unchanged.
192	     *
193	     * @return the human-formatted telephone, or {@code null} when no telephone is stored
194	     */
195	    @Transient
196	    public String getTelephoneDisplay() {
197	        if (this.telephone == null || !this.telephone.startsWith("+")) {
198	            return this.telephone;
199	        }
200	        String allDigits = this.telephone.substring(1);
201	        if (allDigits.isEmpty()) {
202	            return this.telephone;
203	        }
204	        String countryCode = null;
205	        for (String code : KNOWN_COUNTRY_CODES) {
206	            if (allDigits.startsWith(code)) {
207	                countryCode = code;
208	                break;
209	            }
210	        }
211	        if (countryCode == null) {
212	            countryCode = allDigits.substring(0, 1);
213	        }
214	        String national = allDigits.substring(countryCode.length());
215	        StringBuilder display = new StringBuilder("+").append(countryCode);
216	        for (int i = 0; i < national.length(); i += 3) {
217	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
218	        }
219	        return display.toString();
220	    }
