248	     * (the registration date): {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
249	     * and {@code 'SENIOR'} at 65 or older. The completed-years age is the whole number of years
250	     * between the birth date and the reference date. Returns {@code null} when no birth date is
251	     * supplied. When the reference date is absent the current server date is used.
252	     *
253	     * @param birthDate the owner's date of birth, or {@code null} when absent
254	     * @param reference the date to compute the age against (the registration date), may be {@code null}
255	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date
256	     */
257	    public static String ageBandOf(LocalDate birthDate, LocalDate reference) {
258	        if (birthDate == null) {
259	            return null;
260	        }
261	        LocalDate asOf = reference != null ? reference : LocalDate.now();
262	        int years = java.time.Period.between(birthDate, asOf).getYears();
263	        if (years < 18) {
264	            return "MINOR";
265	        }
266	        if (years < 65) {
267	            return "ADULT";
268	        }
269	        return "SENIOR";
270	    }
