457	    /**
458	     * The single derived key used for all duplicate detection: the lower-case hex SHA-256 digest of
459	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}. Two owners are duplicates
460	     * only when their whole identity keys are equal; because the telephone is part of the key, two
461	     * members of the same household with different telephones have different keys and are both
462	     * allowed.
463	     *
464	     * @return the derived identity key as 64 lower-case hex characters
465	     */
466	    @Transient
467	    public String getIdentityKey() {
468	        String seed = (this.telephone == null ? "" : this.telephone) + "|"
469	            + (this.email == null ? "" : this.email.toLowerCase(Locale.ROOT)) + "|"
470	            + soundex(this.getLastName());
471	        return sha256Hex(seed);
472	    }
