474	    /**
475	     * The full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
476	     *
477	     * @param value the source value to hash
478	     * @return the 64-character lower-case hex digest
479	     */
480	    private static String sha256Hex(String value) {
481	        try {
482	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
483	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
484	            StringBuilder sb = new StringBuilder(digest.length * 2);
485	            for (byte b : digest) {
486	                sb.append(String.format("%02x", b));
487	            }
488	            return sb.toString();
489	        }
490	        catch (java.security.NoSuchAlgorithmException e) {
491	            throw new IllegalStateException("SHA-256 not available", e);
492	        }
493	    }
