495	    /**
496	     * The American Soundex code of a name: its first letter followed by three digits derived from
497	     * the remaining consonants ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2}; {@code d,t -> 3};
498	     * {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w} are not coded).
499	     * Adjacent letters mapping to the same digit (including when separated only by {@code h} or
500	     * {@code w}) are coded once, while a vowel between them resets the run so the digit is coded
501	     * again. The code is right-padded with zeros and truncated to length four. A {@code null} or
502	     * letter-free name yields {@code '0000'}.
503	     *
504	     * @param name the name to encode
505	     * @return the four-character Soundex code
506	     */
507	    public static String soundex(String name) {
508	        String s = (name == null ? "" : name).toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
509	        if (s.isEmpty()) {
510	            return "0000";
511	        }
512	        char first = s.charAt(0);
513	        StringBuilder code = new StringBuilder().append(first);
514	        char prevDigit = soundexDigit(first);
515	        for (int i = 1; i < s.length() && code.length() < 4; i++) {
516	            char c = s.charAt(i);
517	            char digit = soundexDigit(c);
518	            if (digit != '0' && digit != prevDigit) {
519	                code.append(digit);
520	            }
521	            if (c != 'H' && c != 'W') {
522	                prevDigit = digit;
523	            }
524	        }
525	        while (code.length() < 4) {
526	            code.append('0');
527	        }
528	        return code.toString();
529	    }
