557	    /**
558	     * A single Luhn check digit (0-9) computed over the digits contained in the
559	     * {@code customerCode}. Non-digit characters (such as the letter prefixes and the
560	     * separators) are ignored; a {@code null} customer code is treated as having no digits.
561	     *
562	     * @return the Luhn check digit for the customer code
563	     */
564	    @Transient
565	    public int getCheckDigit() {
566	        String source = this.customerCode == null ? "" : this.customerCode;
567	        int sum = 0;
568	        boolean dbl = true;
569	        for (int i = source.length() - 1; i >= 0; i--) {
570	            char c = source.charAt(i);
571	            if (c < '0' || c > '9') {
572	                continue;
573	            }
574	            int d = c - '0';
575	            if (dbl) {
576	                d *= 2;
577	                if (d > 9) {
578	                    d -= 9;
579	                }
580	            }
581	            sum += d;
582	            dbl = !dbl;
583	        }
584	        return (10 - (sum % 10)) % 10;
585	    }
