59	    /**
60	     * Monotonically increasing sequence assigned to each {@code OWNER_CREATED} structured event, in
61	     * the order owners are created across this application instance. Shared across all requests.
62	     */
63	    private static final java.util.concurrent.atomic.AtomicLong OWNER_EVENT_SEQ =
64	        new java.util.concurrent.atomic.AtomicLong();
