275	    /**
276	     * Reads the current request's {@code Idempotency-Key} header, if any. Returns the trimmed header
277	     * value, or {@code null} when the header is absent, blank, or there is no active request (so a
278	     * request without the header behaves exactly as before).
279	     *
280	     * @return the non-blank idempotency key for the current request, or {@code null}
281	     */
282	    private String currentIdempotencyKey() {
283	        org.springframework.web.context.request.RequestAttributes attrs =
284	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
285	        if (!(attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs)) {
286	            return null;
287	        }
288	        String key = servletAttrs.getRequest().getHeader("Idempotency-Key");
289	        if (key == null || key.isBlank()) {
290	            return null;
291	        }
292	        return key.trim();
293	    }
