295	    /**
296	     * The fixed public-holiday calendar the business-day roll skips. When an adjusted registration
297	     * date lands on one of these dates it is rolled forward to the next non-holiday business day.
298	     */
299	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
300	        java.time.LocalDate.parse("2026-01-01"), java.time.LocalDate.parse("2026-01-26"),
301	        java.time.LocalDate.parse("2026-04-25"), java.time.LocalDate.parse("2026-12-25"),
302	        java.time.LocalDate.parse("2026-12-28"));
303	
304	    /**
305	     * Rolls a registration date forward to a business day. A Saturday, Sunday or listed public
306	     * holiday is advanced one day at a time until it lands on a weekday that is not a public holiday;
307	     * a plain weekday is returned unchanged. This is applied to the effective registration date
308	     * (whether supplied in the request or defaulted to the server date) so that every stored
309	     * {@code registrationDate}, and any value derived from it, lands on a business day.
310	     *
311	     * @param date the effective registration date
312	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
313	     */
314	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
315	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
316	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
317	            || PUBLIC_HOLIDAYS.contains(date)) {
318	            date = date.plusDays(1);
319	        }
320	        return date;
321	    }
