341	    /**
342	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
343	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
344	     * the city when the postcode is absent or in no known range, see
345	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
346	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
347	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
348	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
349	     * a pure function of the owner's region, telephone and last name.
350	     *
351	     * @param city                the owner's city
352	     * @param postcode            the owner's postcode, may be {@code null}
353	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
354	     * @param lastName            the owner's last name
355	     * @return the assigned customer code
356	     */
357	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
358	        String region = org.springframework.samples.petclinic.mapper.Localities
359	            .forCityAndPostcode(city, postcode);
360	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
361	            + (lastName == null ? "" : lastName), 8);
362	        return region + "-" + hash8;
363	    }
364	
365	    /**
366	     * Ensures the computed {@code customerCode} is unique across existing owners. When {@code baseCode}
367	     * does not collide with any existing owner's {@code customerCode} it is returned unchanged.
368	     * Otherwise {@code '-<n>'} is appended, using the smallest {@code n} of 2 or more that yields a
369	     * value not already in use, and that de-duplicated code is returned.
370	     *
371	     * @param baseCode the freshly computed customer code
372	     * @return {@code baseCode} if unused, otherwise {@code baseCode + "-" + n} for the smallest free n
373	     */
374	    private String deduplicateCustomerCode(String baseCode) {
375	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
376	            .map(org.springframework.samples.petclinic.model.Owner::getCustomerCode)
377	            .filter(java.util.Objects::nonNull)
378	            .collect(java.util.stream.Collectors.toSet());
379	        if (!inUse.contains(baseCode)) {
380	            return baseCode;
381	        }
382	        int n = 2;
383	        while (inUse.contains(baseCode + "-" + n)) {
384	            n++;
385	        }
386	        return baseCode + "-" + n;
387	    }
