389	    /**
390	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
391	     * UTF-8 bytes of {@code value}.
392	     *
393	     * @param value  the source value to hash
394	     * @param length the number of leading hex characters to return
395	     * @return the leading upper-case hex characters of the digest
396	     */
397	    private String sha256UpperHex(String value, int length) {
398	        try {
399	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
400	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
401	            StringBuilder sb = new StringBuilder(digest.length * 2);
402	            for (byte b : digest) {
403	                sb.append(String.format("%02x", b));
404	            }
405	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
406	        }
407	        catch (java.security.NoSuchAlgorithmException e) {
408	            throw new IllegalStateException("SHA-256 not available", e);
409	        }
410	    }
