412	    /**
413	     * Normalizes a street address applied whenever an owner is created: leading and trailing
414	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
415	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
416	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
417	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
418	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
419	     * {@code '12 MAIN STREET'}.
420	     *
421	     * @param address the raw address as submitted, or {@code null} when absent
422	     * @return the normalized address, or the empty string when the value is blank
423	     */
424	    /**
425	     * Resolves and normalizes an owner's postal address, accepting either the structured form
426	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
427	     * input for backward compatibility. The structured form is preferred: when a non-blank
428	     * {@code addressLine1} is supplied, both structured lines are normalized (see
429	     * {@link #normalizeAddress(String)}) and the stored {@code address} is composed from them —
430	     * the normalized {@code addressLine1}, with a single space and the normalized
431	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the flat
432	     * {@code address} input is normalized and stored, and the structured lines are cleared.
433	     *
434	     * <p>An owner is valid only when it supplies an address in one of these forms; a request with
435	     * neither a non-blank {@code addressLine1} nor a non-blank flat {@code address} is rejected.
436	     *
437	     * @param owner the owner whose address fields are resolved and normalized in place
438	     * @throws ResponseStatusException with a 400 status when no address is supplied in either form
439	     */
440	    private void applyAddress(Owner owner) {
441	        String line1 = normalizeAddress(owner.getAddressLine1());
442	        String line2 = normalizeAddress(owner.getAddressLine2());
443	        String flat = normalizeAddress(owner.getAddress());
444	        String composed;
445	        if (!line1.isEmpty()) {
446	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
447	            owner.setAddressLine1(line1);
448	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
449	        } else {
450	            composed = flat;
451	            owner.setAddressLine1(null);
452	            owner.setAddressLine2(null);
453	        }
454	        if (composed.isEmpty()) {
455	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
456	                "Address must not be blank after normalization");
457	        }
458	        owner.setAddress(composed);
459	    }
460	
461	    private String normalizeAddress(String address) {
462	        String collapsed = (address == null ? "" : address)
463	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
464	        if (collapsed.isEmpty()) {
465	            return "";
466	        }
467	        String[] tokens = collapsed.split(" ");
468	        for (int i = 0; i < tokens.length; i++) {
469	            switch (tokens[i]) {
470	                case "ST" -> tokens[i] = "STREET";
471	                case "RD" -> tokens[i] = "ROAD";
472	                case "AVE" -> tokens[i] = "AVENUE";
473	                default -> { }
474	            }
475	        }
476	        return String.join(" ", tokens);
477	    }
