479	    /**
480	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
481	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
482	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
483	     * empty string.
484	     *
485	     * @param value the raw value (last name or address) as submitted
486	     * @return the normalized comparison key
487	     */
488	    private String normalizeForHousehold(String value) {
489	        if (value == null) {
490	            return "";
491	        }
492	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
493	    }
