495	    /**
496	     * Derives the stable shared household identifier for a household, keyed on the normalized last
497	     * name and address. Because it is a pure function of those normalized keys, every owner in the
498	     * same household deterministically computes the same value. The identifier is the first 12
499	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
500	     * (the separator prevents distinct name/address pairs from colliding).
501	     *
502	     * @param lastNameKey the normalized last-name comparison key
503	     * @param addressKey  the normalized address comparison key
504	     * @return the stable household identifier
505	     */
506	    private String householdId(String lastNameKey, String postcode) {
507	        String seed = lastNameKey + "|" + (postcode == null ? "" : postcode);
508	        try {
509	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
510	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
511	            StringBuilder sb = new StringBuilder(digest.length * 2);
512	            for (byte b : digest) {
513	                sb.append(String.format("%02x", b));
514	            }
515	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
516	        }
517	        catch (java.security.NoSuchAlgorithmException e) {
518	            throw new IllegalStateException("SHA-256 not available", e);
519	        }
520	    }
