522	    /**
523	     * The exact number of national (subscriber) digits required for a given country calling code,
524	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
525	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
526	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
527	     */
528	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
529	        java.util.Map.of("61", 9, "1", 10);
