531	    /**
532	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
533	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
534	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
535	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
536	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
537	     * is stored as {@code '+61412345678'}.
538	     *
539	     * <p>In addition, when the number's country code has a fixed national-number length (see
540	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
541	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
542	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
543	     *
544	     * @param telephone the raw telephone number as submitted
545	     * @return the normalized E.164 telephone number
546	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
547	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
548	     *         for its country code
549	     */
550	    private String normalizeTelephone(String telephone) {
551	        String raw = telephone == null ? "" : telephone.trim();
552	        String digits = raw.replaceAll("\\D", "");
553	        String e164;
554	        if (raw.startsWith("+")) {
555	            e164 = "+" + digits;
556	        } else {
557	            if (digits.startsWith("0")) {
558	                digits = digits.substring(1);
559	            }
560	            e164 = "+61" + digits;
561	        }
562	        int digitCount = e164.length() - 1;
563	        if (digitCount < 8 || digitCount > 15) {
564	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
565	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
566	        }
567	        validateNationalNumberLength(e164);
568	        return e164;
569	    }
570	
571	    /**
572	     * Validates that an E.164 number's national-number length is correct for its country code.
573	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
574	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
575	     * following it must match exactly. Country codes without a fixed length are left unchecked.
576	     *
577	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
578	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
579	     *         for the country code
580	     */
581	    private void validateNationalNumberLength(String e164) {
582	        String allDigits = e164.substring(1);
583	        String bestCode = null;
584	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
585	            if (allDigits.startsWith(code)
586	                    && (bestCode == null || code.length() > bestCode.length())) {
587	                bestCode = code;
588	            }
589	        }
590	        if (bestCode == null) {
591	            return;
592	        }
593	        int nationalLength = allDigits.length() - bestCode.length();
594	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
595	        if (nationalLength != required) {
596	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
597	                "Telephone for country code '+" + bestCode + "' must have " + required
598	                    + " national digits");
599	        }
600	    }
601	
602	    /**
603	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
604	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
605	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
606	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
607	     */
608	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
609	        "NSW", new int[] {2000, 2099},
610	        "VIC", new int[] {3000, 3099},
611	        "QLD", new int[] {4000, 4099});
612	
613	    /**
614	     * Validates an owner's optional postcode against their city's region. The postcode is only
615	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
616	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
617	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
618	     * postcode must fall within that region's inclusive range; a city with no known region accepts
619	     * any 4-digit postcode.
620	     *
621	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
622	     * @param city     the owner's city, used to derive the region whose range applies
623	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
624	     *         for the city's region
625	     */
626	    private void validatePostcode(String postcode, String city) {
627	        if (postcode == null) {
628	            return;
629	        }
630	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
631	        int[] range = REGION_POSTCODE_RANGES.get(region);
632	        if (range == null) {
633	            return;
634	        }
635	        int value = Integer.parseInt(postcode);
636	        if (value < range[0] || value > range[1]) {
637	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
638	                "Postcode " + postcode + " is not valid for region " + region);
639	        }
640	    }
641	
642	    /**
643	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
644	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
645	     * (absent) or already valid.
646	     *
647	     * @param email the email address as submitted, or {@code null} when absent
648	     * @return the lower-cased email, or {@code null} when absent
649	     */
650	    private String normalizeEmail(String email) {
651	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
652	    }
653	
654	    /**
655	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
656	     * providers are rejected because they cannot be relied on for durable contact.
657	     */
658	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
659	        "mailinator.com", "tempmail.com", "guerrillamail.com");
660	
661	    /**
662	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
663	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
664	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
665	     * (absent) is accepted, keeping the field optional.
666	     *
667	     * @param email the normalized email address, or {@code null} when absent
668	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
669	     */
670	    private void validateEmailDomain(String email) {
671	        if (email == null) {
672	            return;
673	        }
674	        int at = email.lastIndexOf('@');
675	        if (at < 0) {
676	            return;
677	        }
678	        String domain = email.substring(at + 1);
679	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
680	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
681	                "Email domain " + domain + " is not allowed");
682	        }
683	    }
684	
685	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
686	    @Override
687	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
688	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
689	        if (currentOwner == null) {
690	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
691	        }
692	        currentOwner.setAddress(ownerFieldsDto.getAddress());
693	        currentOwner.setCity(ownerFieldsDto.getCity());
694	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
695	        currentOwner.setLastName(ownerFieldsDto.getLastName());
696	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
697	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
698	        this.clinicService.saveOwner(currentOwner);
699	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
700	    }
701	
702	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
703	    @Transactional
704	    @Override
705	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
706	        Owner owner = this.clinicService.findOwnerById(ownerId);
707	        if (owner == null) {
708	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
709	        }
710	        // Soft delete: flag the owner deleted and retain the row rather than removing it.
711	        owner.setDeleted(true);
712	        this.clinicService.saveOwner(owner);
713	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
714	    }
715	
716	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
717	    @Override
718	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
719	        Owner owner = this.clinicService.findOwnerById(ownerId);
720	        if (owner == null) {
721	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
722	        }
723	        HttpHeaders headers = new HttpHeaders();
724	        Pet pet = petMapper.toPet(petFieldsDto);
725	        owner.setId(ownerId);
726	        pet.setOwner(owner);
727	        pet.getType().setName(null);
728	        this.clinicService.savePet(pet);
729	        PetDto petDto = petMapper.toPetDto(pet);
730	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
731	            .buildAndExpand(pet.getId()).toUri());
732	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
733	    }
734	
735	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
736	    @Override
737	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
738	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
739	        if (currentOwner != null) {
740	            Pet currentPet = this.clinicService.findPetById(petId);
741	            if (currentPet != null) {
742	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
743	                currentPet.setName(petFieldsDto.getName());
744	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
745	                this.clinicService.savePet(currentPet);
746	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
747	            }
748	        }
749	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
750	    }
751	
752	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
753	    @Override
754	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
755	        HttpHeaders headers = new HttpHeaders();
756	        Visit visit = visitMapper.toVisit(visitFieldsDto);
757	        Pet pet = new Pet();
758	        pet.setId(petId);
759	        visit.setPet(pet);
760	        this.clinicService.saveVisit(visit);
761	        VisitDto visitDto = visitMapper.toVisitDto(visit);
762	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
763	            .buildAndExpand(visit.getId()).toUri());
764	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
765	    }
766	
767	
768	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
769	    @Override
770	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
771	        Owner owner = this.clinicService.findOwnerById(ownerId);
772	        if (owner != null) {
773	            Pet pet = owner.getPet(petId);
774	            if (pet != null) {
775	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
776	            }
777	        }
778	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
779	    }
780	}
