    /**
     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for vowels and the
     * uncoded letters {@code h} and {@code w}.
     *
     * @param c the upper-case letter to map
     * @return the Soundex digit character, or {@code '0'} when the letter is not coded
     */
    private static char soundexDigit(char c) {
        switch (c) {
            case 'B': case 'F': case 'P': case 'V':
                return '1';
            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
                return '2';
            case 'D': case 'T':
                return '3';
            case 'L':
                return '4';
            case 'M': case 'N':
                return '5';
            case 'R':
                return '6';
            default:
                return '0';
        }
    }

    /**
     * A single Luhn check digit (0-9) computed over the digits contained in the
     * {@code customerCode}. Non-digit characters (such as the letter prefixes and the
     * separators) are ignored; a {@code null} customer code is treated as having no digits.
     *
     * @return the Luhn check digit for the customer code
     */
    @Transient
    public int getCheckDigit() {
        String source = this.customerCode == null ? "" : this.customerCode;
        int sum = 0;
        boolean dbl = true;
        for (int i = source.length() - 1; i >= 0; i--) {
            char c = source.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    protected Set<Pet> getPetsInternal() {
        if (this.pets == null) {
            this.pets = new HashSet<>();
        }
        return this.pets;
    }

