    String customerCode = owner.getCustomerCode();
    if (customerCode != null) {
        int dash = customerCode.indexOf('-');
        if (dash > 0) {
            return customerCode.substring(0, dash);
        }
    }
    return forCityAndPostcode(owner.getCity(), owner.getPostcode());
